if (activeKeyword.isBlank() || liveLoadingMore || !liveHasMore) return

val request = binding.begin("search-live", null)
val requestedKeyword = activeKeyword
val requestedPage = liveNextPage
try {
request.publish {
liveLoadingMore = true
}
binding.requests.searchLive(activeKeyword, liveNextPage, SearchLiveOrder.ONLINE)
    .onOwnedSuccess(request) { (rooms, pageInfo) ->
        val currentIds = liveResults.map { it.roomid }.toSet()
        liveResults.addAll(rooms.filterNot { it.roomid in currentIds })
        liveHasMore = pageInfo.hasMore
        liveNextPage = pageInfo.currentPage + 1
    }
    .onOwnedFailure(request) { error = it.message ?: "直播加载更多失败" }


} finally { request.finish { liveLoadingMore = false } }

if (activeKeyword.isBlank() || userLoadingMore || !userHasMore) return

val request = binding.begin("search-user", null)
val requestedKeyword = activeKeyword
val requestedPage = userNextPage
try {
request.publish {
userLoadingMore = true
}
binding.requests.searchUp(activeKeyword, userNextPage)
    .onOwnedSuccess(request) { (ups, pageInfo) ->
        val currentIds = userResults.map { it.mid }.toSet()
        userResults.addAll(ups.filterNot { it.mid in currentIds })
        userHasMore = pageInfo.hasMore
        userNextPage = pageInfo.currentPage + 1
    }
    .onOwnedFailure(request) { error = it.message ?: "主播加载更多失败" }


} finally { request.finish { userLoadingMore = false } }

